// GithubHeartbeat.js
import React, { useState, useEffect } from 'react';

const GithubHeartbeat = () => {
  const [commitDates, setCommitDates] = useState([]);

  useEffect(() => {
    const fetchCommits = async () => {
      try {
        // Replace <username> and <repo> with your GitHub username and repository name
        const response = await fetch('https://api.github.com/repos/<username>/<repo>/commits');
        const data = await response.json();
        // Extract commit dates from the response
        const commits = data.map(commit => new Date(commit.commit.author.date));
        setCommitDates(commits);
      } catch (error) {
        console.error('Error fetching commits:', error);
      }
    };

    fetchCommits();
  }, []);

  // Generate a heartbeat path using commit dates.
  const generateHeartbeatPath = () => {
    if (commitDates.length === 0) return '';
    // Sort commit dates in ascending order
    const sortedDates = [...commitDates].sort((a, b) => a - b);
    const startTime = sortedDates[0].getTime();
    const endTime = sortedDates[sortedDates.length - 1].getTime();
    const timeRange = endTime - startTime || 1; // avoid division by zero

    // Begin path at the baseline
    let path = 'M0 50 ';

    sortedDates.forEach((date, index) => {
      // Map the commit time to an x-position (for a 500px wide SVG)
      const x = ((date.getTime() - startTime) / timeRange) * 500;
      // For each commit, add a spike: down/up/down to mimic a heartbeat
      path += `L${x} 50 L${x} 30 L${x + 10} 70 L${x + 20} 50 `;
    });

    // End the path
    path += 'L520 50';
    return path;
  };

  return (
    <div style={{ marginTop: '40px' }}>
      <h3 style={{ fontFamily: "'SF Pro Display', sans-serif", fontWeight: 500 }}>GitHub Heartbeat</h3>
      <svg width="540" height="100">
        <path
          d={generateHeartbeatPath()}
          fill="none"
          stroke="#FF0000"
          strokeWidth="2"
          style={{ transition: 'all 0.5s ease-in-out' }}
        />
      </svg>
    </div>
  );
};

export default GithubHeartbeat;
